#' Analyze SNP Associations With Two Outcomes
#'
#' Perform SNP-level association analyses and polygenic risk score (PRS)
#' analyses for two outcomes using data generated by
#' [simulate_snps_two_outcomes()].
#'
#' The function performs four analyses:
#'
#' \enumerate{
#'   \item Simple linear regression of `y1` on each SNP individually.
#'   \item Simple linear regression of `y2` on each SNP individually.
#'   \item Construction of an individual-level PRS using the SNP dosage
#'         multiplied by the SNP's `y1` association statistic (`z1`),
#'         followed by regression of `y2` on the PRS.
#'   \item Joint PRS association analysis using the existing
#'         [prs_assoc_core()] function.
#' }
#'
#' For the first two analyses, the SNP effect estimate, standard error,
#' z statistic, and p-value are returned for every SNP. For the third
#' analysis, the PRS effect estimate, standard error, z statistic, and
#' p-value are returned. The fourth analysis returns the four quantities
#' returned by [prs_assoc_core()].
#'
#' @param data A list returned by
#'   [simulate_snps_two_outcomes()]. The list must contain `G`, `y1`,
#'   `y2`, and `maf`.
#'
#' @return A list with four components:
#' \describe{
#'   \item{y1_snp}{
#'     A data frame containing the SNP-level association results for
#'     `y1`. Columns are `snp`, `beta1`, `se1`, `z1`, and `p_value1`.
#'   }
#'   \item{y2_snp}{
#'     A data frame containing the SNP-level association results for
#'     `y2`. Columns are `snp`, `beta2`, `se2`, `z2`, and `p_value2`.
#'   }
#'   \item{prs}{
#'     A list containing the individual-level PRS and the results from
#'     regressing `y2` on the PRS. The regression results are named
#'     `beta`, `se`, `z`, and `p_value`.
#'   }
#'   \item{prs_assoc_core}{
#'     A numeric vector returned by [prs_assoc_core()] containing
#'     `effect_est`, `effect_se`, `Z_a`, and `p_value`.
#'   }
#' }
#'
#' @details
#' For each SNP, the function fits the model
#'
#' \deqn{
#' y_k = \alpha_k + G_j \beta_{kj} + \epsilon,
#' }
#'
#' separately for each outcome and SNP, where `G_j` is the SNP dosage.
#'
#' The SNP-level z statistic is calculated as
#'
#' \deqn{
#' z_{kj} = \frac{\hat{\beta}_{kj}}{SE(\hat{\beta}_{kj})}.
#' }
#'
#' The PRS is constructed as
#'
#' \deqn{
#' PRS_i = \sum_{j=1}^{N} z_{1j}G_{ij},
#' }
#'
#' where `z1` is the SNP-level association statistic from the analysis
#' of `y1`.
#'
#' The third analysis fits the model
#'
#' \deqn{
#' y_2 = \alpha + PRS\beta_{PRS} + \epsilon.
#' }
#'
#' For the fourth analysis, `prs_assoc_core()` is called with:
#'
#' \itemize{
#'   \item `w_i = z1`
#'   \item `var_x = 2 * maf * (1 - maf)`
#'   \item `b_hat = beta2`
#'   \item `var_b_hat = se2^2`
#' }
#'
#' The `var_x` supplied to `prs_assoc_core()` is the theoretical
#' genotype variance under Hardy-Weinberg equilibrium.
#'
#' @examples
#' # Simulate data
#' sim <- simulate_snps_two_outcomes(
#'   N = 100,
#'   M = 30,
#'   same_direction = TRUE,
#'   n_ind = 1000,
#'   seed = 123
#' )
#'
#' # Run all four analyses
#' results <- analyze_snps_two_outcomes(sim)
#'
#' # SNP-level results for y1
#' head(results$y1_snp)
#'
#' # SNP-level results for y2
#' head(results$y2_snp)
#'
#' # PRS association result
#' results$prs$association
#'
#' # prs_assoc_core result
#' results$prs_assoc_core
#'
#' @export
analyze_snps_two_outcomes <- function(data) {
	
	# ------------------------------------------------------------
	# Input validation
	# ------------------------------------------------------------
	
	if (!is.list(data)) {
		stop("data must be a list returned by simulate_snps_two_outcomes().")
	}
	
	required_names <- c("G", "y1", "y2", "maf")
	
	missing_names <- setdiff(required_names, names(data))
	
	if (length(missing_names) > 0) {
		stop(
				"data is missing required components: ",
				paste(missing_names, collapse = ", ")
		)
	}
	
	G <- data$G
	y1 <- data$y1
	y2 <- data$y2
	maf <- data$maf
	
	# Check genotype matrix
	if (!is.matrix(G)) {
		stop("data$G must be a matrix.")
	}
	
	n_ind <- nrow(G)
	N <- ncol(G)
	
	if (length(y1) != n_ind) {
		stop("Length of y1 must equal the number of rows of G.")
	}
	
	if (length(y2) != n_ind) {
		stop("Length of y2 must equal the number of rows of G.")
	}
	
	if (length(maf) != N) {
		stop("Length of maf must equal the number of columns of G.")
	}
	
	if (anyNA(G) || anyNA(y1) || anyNA(y2) || anyNA(maf)) {
		stop("G, y1, y2, and maf must not contain missing values.")
	}
	
	if (any(maf <= 0 | maf > 0.5)) {
		stop("All MAF values must be greater than 0 and no greater than 0.50.")
	}
	
	# ------------------------------------------------------------
	# Helper function for SNP-level linear regression
	# ------------------------------------------------------------
	
	fit_single_snp <- function(x, y) {
		
		x_centered <- x - mean(x)
		y_centered <- y - mean(y)
		
		sxx <- sum(x_centered^2)
		
		if (sxx == 0) {
			return(
					c(
							beta = NA_real_,
							se = NA_real_,
							z = NA_real_,
							p_value = NA_real_
					)
			)
		}
		
		beta <- sum(x_centered * y_centered) / sxx
		
		residuals <- y - mean(y) - beta * x_centered
		
		df <- length(y) - 2L
		
		residual_variance <- sum(residuals^2) / df
		
		se <- sqrt(residual_variance / sxx)
		
		z <- beta / se
		
		# Two-sided p-value
		p_value <- 2 * pt(
				abs(z),
				df = df,
				lower.tail = FALSE
		)
		
		c(
				beta = beta,
				se = se,
				z = z,
				p_value = p_value
		)
	}
	
	# ------------------------------------------------------------
	# Analysis 1:
	# Regress y1 on every SNP
	# ------------------------------------------------------------
	
	y1_results <- matrix(
			NA_real_,
			nrow = N,
			ncol = 4L
	)
	
	colnames(y1_results) <- c(
			"beta1",
			"se1",
			"z1",
			"p_value1"
	)
	
	for (j in seq_len(N)) {
		
		y1_results[j, ] <- fit_single_snp(
				x = G[, j],
				y = y1
		)
	}
	
	y1_snp <- data.frame(
			snp = if (!is.null(colnames(G))) {
						colnames(G)
					} else {
						paste0("SNP", seq_len(N))
					},
			y1_results,
			row.names = NULL,
			check.names = FALSE
	)
	
	# ------------------------------------------------------------
	# Analysis 2:
	# Regress y2 on every SNP
	# ------------------------------------------------------------
	
	y2_results <- matrix(
			NA_real_,
			nrow = N,
			ncol = 4L
	)
	
	colnames(y2_results) <- c(
			"beta2",
			"se2",
			"z2",
			"p_value2"
	)
	
	for (j in seq_len(N)) {
		
		y2_results[j, ] <- fit_single_snp(
				x = G[, j],
				y = y2
		)
	}
	
	y2_snp <- data.frame(
			snp = if (!is.null(colnames(G))) {
						colnames(G)
					} else {
						paste0("SNP", seq_len(N))
					},
			y2_results,
			row.names = NULL,
			check.names = FALSE
	)
	
	# ------------------------------------------------------------
	# Analysis 3:
	# Construct PRS using z1 * dosage
	# ------------------------------------------------------------
	
	z1 <- y1_snp$z1
	
	PRS <- as.vector(
			G %*% z1
	)
	
	# Regress y2 on PRS
	prs_fit <- fit_single_snp(
			x = PRS,
			y = y2
	)
	
	prs_association <- c(
			beta = unname(prs_fit["beta"]),
			se = unname(prs_fit["se"]),
			z = unname(prs_fit["z"]),
			p_value = unname(prs_fit["p_value"])
	)
	
	# ------------------------------------------------------------
	# Analysis 4:
	# Call prs_assoc_core()
	# ------------------------------------------------------------
	
	w_i <- y1_snp$z1
	
	var_x <- 2 * maf * (1 - maf)
	
	b_hat <- y2_snp$beta2
	
	var_b_hat <- y2_snp$se2^2
	
	core_results <- prs_assoc_core(
			w_i = w_i,
			var_x = var_x,
			b_hat = b_hat,
			var_b_hat = var_b_hat
	)
	
	# Check output from prs_assoc_core()
	expected_core_names <- c(
			"effect_est",
			"effect_se",
			"Z_a",
			"p_value"
	)
	
	if (!is.numeric(core_results) ||
			length(core_results) != 4L) {
		stop(
				"prs_assoc_core() must return a numeric vector of length 4."
		)
	}
	
	if (!all(expected_core_names %in% names(core_results))) {
		stop(
				"prs_assoc_core() must return values named: ",
				paste(expected_core_names, collapse = ", ")
		)
	}
	
	# ------------------------------------------------------------
	# Return all results
	# ------------------------------------------------------------
	
	return(
			list(
					y1_snp = y1_snp,
					y2_snp = y2_snp,
					
					prs = list(
							score = PRS,
							association = prs_association
					),
					
					prs_assoc_core = core_results
			)
	)
}
